import random
import math

def run_trial(seed: int) -> dict:
    random.seed(seed)

    def gaussian_elimination(A):
        m, n = len(A), len(A[0])
        for i in range(m):
            max_row = i + max(range(i, m), key=lambda r: abs(A[r][i]))
            A[i], A[max_row] = A[max_row], A[i]
            if A[i][i] == 0:
                continue
            for j in range(n):
                A[i][j] /= A[i][i]
            for k in range(m):
                if k != i and A[k][i] != 0:
                    factor = A[k][i]
                    for j in range(n):
                        A[k][j] -= factor * A[i][j]
        return A

    def matrix_multiplication(A, B):
        m, n, p = len(A), len(B), len(B[0])
        C = [[0]*p for _ in range(m)]
        for i in range(m):
            for j in range(p):
                for k in range(n):
                    C[i][j] += A[i][k] * B[k][j]
        return C

    def is_independent(v, basis):
        if not basis:
            return True
        for b in basis:
            if all(b[j] == v[j] for j in range(len(b))):
                return False
        return True

    def add_to_basis(v, basis):
        if is_independent(v, basis):
            basis.append(v)
        return basis

    def generate_semantic_types(n):
        types = set()
        for i in range(1 << n):
            type_ = tuple((i >> j) & 1 for j in range(n))
            types.add(type_)
        return types

    def assign_semantic_types(clauses, types):
        assignment = {}
        for clause in clauses:
            for t in types:
                if all(abs(c) == t[i] for i, c in enumerate(clause)):
                    assignment[clause] = t
                    break
        return assignment

    def calculate_width(assignment):
        basis = []
        for clause in assignment:
            v = tuple(1 if abs(c) in assignment else 0 for c in clause)
            add_to_basis(v, basis)
        return len(basis)

    n = random.randint(5, 40)
    clauses = [[random.choice([-1, 1]) * (i + 1) for i in range(n)] for _ in range(n)]
    types = generate_semantic_types(n)
